package org.xaspire.WuhouCake.order.domain.model.valobj;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.regex.Pattern;

/** Extracts price lines generated by the previous draft recovery implementation. */
public record LegacyDraftQuote(Map<String, Object> attributes, Long unitPriceCents, Long memberPriceCents) {
    private static final Pattern LINE = Pattern.compile("^(原商品单价|原会员单价)：(.+) 元（仅供参考）$");

    public static LegacyDraftQuote extract(Map<String, Object> attributes) {
        if (attributes == null || !(attributes.get("specification") instanceof String specification))
            return new LegacyDraftQuote(attributes, null, null);
        var lines = new ArrayList<String>();
        Long unit = null, member = null;
        boolean extracted = false;
        for (String line : specification.split("\\r?\\n", -1)) {
            var match = LINE.matcher(line);
            if (!match.matches()) { lines.add(line); continue; }
            extracted = true;
            Long cents = cents(match.group(2));
            if (match.group(1).equals("原商品单价")) {
                if (unit == null) unit = cents;
            } else if (member == null) member = cents;
        }
        String clean = String.join("\n", lines);
        if (!extracted) return new LegacyDraftQuote(attributes, unit, member);
        var cleaned = new LinkedHashMap<>(attributes);
        if (clean.isBlank()) cleaned.remove("specification"); else cleaned.put("specification", clean);
        return new LegacyDraftQuote(cleaned, unit, member);
    }

    private static Long cents(String raw) {
        if (!raw.matches("[0-9]+(?:\\.[0-9]{1,2})?")) return null;
        try { return OrderValues.money(new BigDecimal(raw).movePointRight(2)); }
        catch (OrderFailure invalid) { return null; }
    }
}
